import type { Anim, Asset, Bone, Idx, Settings } from "./core";
export type Tool = "pen" | "erase" | "fill" | "line" | "rect" | "shade" | "pick" | "bone" | "weight" | "layer" | "pose";
export interface Brush { size: number; shape: "square" | "round"; mirror: boolean; dither: boolean; rectFill: boolean; shadeMode: "darken" | "lighten" }
export interface EditorState {
  curId: number | null; viewN: number; tool: Tool; showGrid: boolean; selSw: number;
  editTarget: { anim: number; f: number } | null;
  selBone: number | null; curFrame: number; tlPlaying: boolean;
  brush: Brush; rigBrush: { r: number; strength: number; mode: "add" | "sub" | "smooth" };
  onion: boolean; colorMode: boolean; eraseMode: boolean; areaColor: string;
  showMesh: boolean; showLayers: boolean; showBones: boolean; viewPx: number; version: number;
}
export interface Display { a: Asset; N: number; disp: Idx; onion: Idx | null; still: Idx; frames: Idx[] | null }
export interface Mods { shift: boolean; alt: boolean; ctrl: boolean }
export interface PoseFields { bone: string; frame: number; keyed: boolean; ease: string; rot: number; x: number; y: number; sx: number; sy: number }

